const TASTE_ICON: Record<FeticheTaste, string> = {
    loved: '❤️',
    liked: '🙂',
    neutral: '😐',
    disliked: '😕',
    hated: '🤢',
};

const TASTE_SORT: Record<FeticheTaste, number> = {
    loved: 0,
    liked: 1,
    neutral: 2,
    disliked: 3,
    hated: 4,
};

let lastSnapshot: FeticheSnapshot | null = null;

function feticheT(
    game: GameRuntime,
    key: string,
    fallbackFr: string,
    fallbackEn: string,
    vars: Record<string, string | number> = {},
): string {
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    const fallbackTemplate = lang === 'en' ? fallbackEn : fallbackFr;
    let template = fallbackTemplate;
    if (typeof game.t === 'function') {
        const i18nKey = `fetiche.${key}`;
        if (Object.keys(vars).length > 0) {
            const out = game.t(i18nKey, vars);
            if (out && out !== i18nKey) template = out;
        } else {
            const preserve: Record<string, string> = {};
            for (const m of fallbackTemplate.matchAll(/\{(\w+)\}/g)) {
                preserve[m[1]!] = `{${m[1]}}`;
            }
            const out = game.t(i18nKey, preserve);
            if (out && out !== i18nKey) template = out;
        }
    }
    return template.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? `{${k}}`));
}

function moodLabel(game: GameRuntime, moodKey: string): string {
    return feticheT(game, `mood.${moodKey}`, moodKey, moodKey);
}

function formatDurationMs(game: GameRuntime, ms: number): string {
    const totalSec = Math.max(0, Math.floor(ms / 1000));
    const h = Math.floor(totalSec / 3600);
    const m = Math.floor((totalSec % 3600) / 60);
    if (h > 0) return `${h}h ${m}m`;
    if (m > 0) return `${m}m`;
    return `${totalSec}s`;
}

function berryDisplay(game: GameRuntime, berryKey: string): { name: string; iconUrl: string } {
    const item = ALL_ITEMS[berryKey as keyof typeof ALL_ITEMS] as { name?: string; img?: string; icon?: string } | undefined;
    const name = typeof game.localizeItemName === 'function'
        ? game.localizeItemName(berryKey, item?.name ?? berryKey)
        : (item?.name ?? berryKey);
    const iconUrl = item?.img || item?.icon || '';
    return { name, iconUrl };
}

function berryItemDescription(game: GameRuntime, berryKey: string): string {
    const def = (ALL_ITEMS as Record<string, Record<string, unknown>>)[berryKey];
    const fallback = String(def?.description ?? '');
    if (typeof game.getLocalizedItemDescription === 'function') {
        return game.getLocalizedItemDescription(berryKey, fallback, def);
    }
    return fallback;
}

function gainsFromStatBlock(stats: FeticheStatBlock, transmissionSec: number): FeticheStatBlock {
    const rate = FETICHE.gainsRate;
    const sec = Math.max(1, transmissionSec);
    return {
        hp: Math.floor(stats.hp * rate * sec),
        attack: Math.floor(stats.attack * rate * sec),
        spattack: Math.floor(stats.spattack * rate * sec),
        defense: Math.floor(stats.defense * rate * sec),
        spdefense: Math.floor(stats.spdefense * rate * sec),
        speed: Math.floor(stats.speed * rate * sec),
    };
}

function buildBerryFeedRow(
    game: GameRuntime,
    berryKey: string,
    taste: FeticheTaste,
    qty: number,
    canFeed: boolean,
): FeticheBerryFeedSnapshot {
    const { name, iconUrl } = berryDisplay(game, berryKey);
    const base = getFeticheBerryStatEffect(berryKey);
    const statEffect = scaleFeticheBerryStatEffect(base, FETICHE_TASTE_EFFECTS[taste].statEffMult);
    return {
        berryKey,
        name,
        iconUrl,
        description: berryItemDescription(game, berryKey),
        qty,
        taste,
        tasteIcon: TASTE_ICON[taste],
        tasteSort: TASTE_SORT[taste],
        statHint: formatFeticheBerryStatHint(statEffect),
        statEffect,
        canFeed,
    };
}

export function ensureFeticheState(game: GameRuntime): import('../types/game/state.js').FeticheState {
    if (!game.feticheState) {
        game.feticheState = createDefaultFeticheState(Date.now());
    }
    const normalized = normalizeFeticheState(game.feticheState, Date.now());
    game.feticheState = normalized;
    return normalized;
}

export function buildFeticheSnapshot(game: GameRuntime, visible = false, now = Date.now()): FeticheSnapshot {
    const state = ensureFeticheState(game);

    const ui = {
        title: feticheT(game, 'title', 'Pokémon Fétiche', 'Favorite Pokémon'),
        chooseTitle: feticheT(game, 'chooseTitle', 'Choisis ton compagnon', 'Choose your companion'),
        chooseHint: feticheT(game, 'chooseHint', 'Choix définitif parmi les espèces capturées.', 'Permanent choice among caught species.'),
        chooseEmpty: feticheT(
            game,
            'chooseEmpty',
            'Aucune forme de base capturée. Capture-en une pour choisir ton Fétiche.',
            'No base form caught yet. Catch one to choose your favorite.',
        ),
        chooseConfirm: feticheT(game, 'chooseConfirm', 'Confirmer le choix', 'Confirm choice'),
        chooseConfirmPrompt: feticheT(
            game,
            'chooseConfirmPrompt',
            'Choix définitif : {name}. Confirmer ?',
            'Permanent choice: {name}. Confirm?',
        ),
        levelLabel: feticheT(game, 'levelLabel', 'Niveau', 'Level'),
        xpLabel: feticheT(game, 'xpLabel', 'XP', 'XP'),
        satietyLabel: feticheT(game, 'satietyLabel', 'Satiété', 'Satiety'),
        hungryLabel: feticheT(game, 'hungryLabel', 'A faim', 'Hungry'),
        crampLabel: feticheT(game, 'crampLabel', 'Mal au ventre', 'Stomach cramp'),
        moodTitle: feticheT(game, 'moodTitle', 'Goûts du moment', 'Current tastes'),
        moodCountdown: feticheT(game, 'moodCountdown', 'Change dans {time}', 'Changes in {time}'),
        lovesLabel: feticheT(game, 'lovesLabel', 'Adore', 'Loves'),
        hatesLabel: feticheT(game, 'hatesLabel', 'Déteste', 'Hates'),
        feedTitle: feticheT(game, 'feedTitle', 'Nourrir', 'Feed'),
        noBerries: feticheT(game, 'noBerries', 'Aucune baie dans le sac.', 'No berries in bag.'),
        notHungry: feticheT(game, 'notHungry', 'Pas faim pour l\'instant.', 'Not hungry right now.'),
        satietyFull: feticheT(
            game,
            'satietyFull',
            'Rassasié — aucune baie ne rentre sans dépasser 100.',
            'Full — no berry fits without exceeding 100.',
        ),
        gainsHint: feticheT(
            game,
            'gainsHint',
            'Les stats affichées suivent le niveau de ton Fétiche. Sa contribution aux gains par seconde grandit avec le temps passé à tes côtés depuis ton choix. Ce bonus s\'ajoute à tes gains passifs — il ne modifie pas directement les stats de ton équipe.',
            'The stats shown follow your Fétiche\'s level. Its contribution to gains per second grows the longer it has been with you since you chose it. This bonus adds to your passive gains — it does not directly change your team\'s stats.',
        ),
        statsTitle: feticheT(game, 'statsTitle', 'Stats & contribution', 'Stats & contribution'),
        xpProgress: feticheT(game, 'xpProgress', '{current} / {next} XP', '{current} / {next} XP'),
        gainsNowLabel: feticheT(game, 'gainsNowLabel', '+{value}/s', '+{value}/s'),
        gainsNextLevelHint: feticheT(game, 'gainsNextLevelHint', '→ {value}', '→ {value}'),
        gainsTotalLabel: feticheT(game, 'gainsTotalLabel', 'Contribution totale : +{value}/s', 'Total contribution: +{value}/s'),
        transmissionLabel: feticheT(
            game,
            'transmissionLabel',
            'Depuis le choix : {sec}s — gains/s = stat × {sec}',
            'Since choice: {sec}s — gains/s = stat × {sec}',
        ),
        maxLevelLabel: feticheT(game, 'maxLevelLabel', 'Niveau max', 'Max level'),
        evolutionToast: feticheT(
            game,
            'evolutionToast',
            '{name} a évolué !',
            '{name} evolved!',
        ),
        tasteLoved: feticheT(game, 'taste.loved', 'Adoré', 'Loved'),
        tasteLiked: feticheT(game, 'taste.liked', 'Aime', 'Liked'),
        tasteNeutral: feticheT(game, 'taste.neutral', 'Neutre', 'Neutral'),
        tasteDisliked: feticheT(game, 'taste.disliked', 'N\'aime pas', 'Disliked'),
        tasteHated: feticheT(game, 'taste.hated', 'Déteste', 'Hated'),
        berryStatHint: feticheT(game, 'berryStatHint', 'Effet stats', 'Stat effect'),
    };

    const speciesChoices = getCaughtFeticheBaseSpeciesKeys(game.pokedex ?? {}).map((speciesKey) => ({
        speciesKey,
        name: uiPokemonName(game, speciesKey),
        spriteUrl: feticheShowcaseSpriteUrl(speciesKey),
    }));

    const hasChosen = !!state.speciesKey;
    const displayKey = hasChosen ? getFeticheDisplaySpecies(state) : '';
    const speciesName = hasChosen
        ? uiPokemonName(game, state.speciesKey!)
        : '';
    const displaySpeciesName = hasChosen && displayKey
        ? uiPokemonName(game, displayKey)
        : '';
    const spriteUrl = hasChosen && displayKey
        ? feticheShowcaseSpriteUrl(displayKey)
        : '';

    const xpToNext = hasChosen ? getFeticheXpToNextLevel(state.level) : 0;
    const xpPct = xpToNext > 0 ? Math.min(100, Math.floor((state.xp / xpToNext) * 100)) : 0;
    const isMaxLevel = hasChosen && state.level >= FETICHE.maxLevel;
    const transmissionSec = hasChosen ? getFeticheTransmissionSeconds(state, now) : 0;
    const gainsPerSec = hasChosen ? getFeticheStatsForGains(state, now) : {
        hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0,
    };
    const stats: FeticheStatBlock = {
        hp: state.stats.hp,
        attack: state.stats.attack,
        spattack: state.stats.spattack,
        defense: state.stats.defense,
        spdefense: state.stats.spdefense,
        speed: state.stats.speed,
    };
    let statsAtNextLevel: FeticheStatBlock | null = null;
    let gainsAtNextLevel: FeticheStatBlock | null = null;
    if (hasChosen && state.speciesKey && !isMaxLevel) {
        const nextDisplay = resolveFeticheDisplaySpecies(state.speciesKey, state.level + 1);
        statsAtNextLevel = getFeticheBaseStatsAtLevel(nextDisplay, state.level + 1);
        gainsAtNextLevel = gainsFromStatBlock(statsAtNextLevel, transmissionSec);
    }
    const gainsTotalPerSec = Object.values(gainsPerSec).reduce((sum, n) => sum + (Number(n) || 0), 0);

    let mood: FeticheMoodUiSnapshot | null = null;
    let feedBerries: FeticheBerryFeedSnapshot[] = [];
    const hasStomachCramp = (Number(state.stomachCrampUntil) || 0) > now;

    if (hasChosen && state.speciesKey) {
        const types = getSpeciesElementTypes(state.speciesKey);
        const moodRaw = getFeticheMoodSnapshot(state, types, now);
        const board = buildFeticheTasteBoard(state, types, now);
        const items = game.items ?? {};

        feedBerries = BERRY_DEX_KEYS
            .filter((key) => (Number(items[key]) || 0) > 0)
            .map((key) => {
                const taste = board[key] ?? 'neutral';
                const canFeed = !hasStomachCramp && canFeedFeticheBerry(state, key, types, now);
                return buildBerryFeedRow(game, key, taste, Number(items[key]) || 0, canFeed);
            })
            .sort((a, b) => a.tasteSort - b.tasteSort || a.name.localeCompare(b.name));

        if (moodRaw) {
            const cravingLabels = moodRaw.cravingBerryKeys.map((k) => berryDisplay(game, k).name);
            mood = {
                moodKey: moodRaw.moodKey,
                moodLabel: moodLabel(game, moodRaw.moodKey),
                countdownMs: moodRaw.countdownMs,
                countdownLabel: ui.moodCountdown.replace('{time}', formatDurationMs(game, moodRaw.countdownMs)),
                cravingBerryKeys: moodRaw.cravingBerryKeys,
                cravingLabels,
                cravings: moodRaw.cravingBerryKeys.map((k) => (
                    buildBerryFeedRow(game, k, board[k] ?? 'neutral', Number(items[k]) || 0, false)
                )),
                lovedNow: moodRaw.lovedNow.map((k) => (
                    buildBerryFeedRow(game, k, board[k] ?? 'loved', Number(items[k]) || 0, false)
                )),
                hatedNow: moodRaw.hatedNow.map((k) => (
                    buildBerryFeedRow(game, k, board[k] ?? 'hated', Number(items[k]) || 0, false)
                )),
            };
        }
    }

    const crampCountdownMs = hasStomachCramp
        ? Math.max(0, (Number(state.stomachCrampUntil) || 0) - now)
        : 0;
    const crampCountdownLabel = hasStomachCramp
        ? formatDurationMs(game, crampCountdownMs)
        : '';

    const cravingBerryInBag = hasChosen && !!mood?.cravingBerryKeys.some(
        (key) => (Number(game.items?.[key]) || 0) > 0,
    );

    return {
        visible,
        featureUnlocked: !!game.unlockedFeatures?.fetiche,
        hasChosen,
        speciesKey: state.speciesKey,
        displaySpeciesKey: hasChosen ? displayKey : null,
        speciesName,
        displaySpeciesName,
        spriteUrl,
        level: state.level,
        xp: state.xp,
        xpToNext,
        xpPct,
        isMaxLevel,
        stats,
        gainsPerSec,
        statsAtNextLevel,
        gainsAtNextLevel,
        gainsTotalPerSec,
        transmissionSec,
        satiety: Math.floor(state.satiety),
        satietyMax: FETICHE.satietyMax,
        satietyPct: Math.min(100, Math.floor((state.satiety / FETICHE.satietyMax) * 100)),
        isHungry: feedBerries.some((b) => b.canFeed),
        stomachCrampUntil: state.stomachCrampUntil,
        hasStomachCramp,
        crampCountdownMs,
        crampCountdownLabel,
        moodChangedPending: !!state.moodChangedPending,
        showOnboarding: !!game.unlockedFeatures?.fetiche && !state.feticheOnboardingSeen,
        headerHungryBadge: !!game.unlockedFeatures?.fetiche
            && (feedBerries.some((b) => b.canFeed) || !!state.moodChangedPending),
        cravingBerryInBag: !!game.unlockedFeatures?.fetiche && cravingBerryInBag,
        mood,
        speciesChoices,
        feedBerries,
        ui,
    };
}

export function feticheSnapshotWouldChange(a: FeticheSnapshot, b: FeticheSnapshot): boolean {
    return JSON.stringify(a) !== JSON.stringify(b);
}

export function notifyFeticheChanged(game: GameRuntime, options?: { force?: boolean; visible?: boolean }): void {
    const visible = options?.visible ?? isMasteryFetichePanelVisible();
    const snap = buildFeticheSnapshot(game, visible);
    if (!options?.force && lastSnapshot && !feticheSnapshotWouldChange(lastSnapshot, snap)) {
        return;
    }
    lastSnapshot = snap;
    publish({ type: Evt.FETICHE_CHANGED, fetiche: snap });
    if (game.miltankFarmViewActive) {
        notifyMiltankFarmChanged(game);
    }
}

/** @internal Vitest */
export function resetFeticheSnapshotDedupForTests(): void {
    lastSnapshot = null;
}
